<?php use App\Core\CSRF; ?>
<div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-4"><div><h1 class="h3 mb-1">Ordens / Serviços automotivos</h1><p class="text-secondary mb-0">Acompanhe o veículo da chegada à entrega.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="/auto/bays">Boxes</a><a class="btn btn-primary" href="/appointments/create">Agendamento interno</a></div></div>
<?php if($pendingAppointments):?><div class="card mb-4"><div class="card-header"><strong>Agendamentos automotivos ainda sem ordem</strong></div><div class="table-responsive"><table class="table mb-0"><tbody><?php foreach($pendingAppointments as $a):?><tr><td><?=date('d/m H:i',strtotime($a['starts_at']))?></td><td><?=htmlspecialchars($a['customer_name'])?></td><td><?=htmlspecialchars($a['service_name'])?></td><td><?=htmlspecialchars(($a['model']??'').' '.($a['plate']??''))?></td><td><form method="post" action="/auto/jobs"><?=CSRF::field()?><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><button class="btn btn-sm btn-primary">Criar ordem</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
